         // org/sonar/sqale/  -> rootDirectory is org/sonar/sqale
         // org/sonar/sqale  -> rootDirectory is org/sonar/sqale
         String rootDirectory = rootPath;
         if (StringUtils.substringAfterLast(rootPath, "/").indexOf('.') >= 0) {
           rootDirectory = StringUtils.substringBeforeLast(rootPath, "/");
         }
