 	    bv.saveImage(classifierNameNew+"_"+i.relationName()
 			 +"_X"+xatt+"_Y"+yatt+".jpg");
 	  }
 	});

       jf.getContentPane().add(bv, BorderLayout.CENTER);
       jf.setSize(bv.getMinimumSize());
       //      jf.setSize(200,200);
       jf.addWindowListener(new java.awt.event.WindowAdapter() {
