       String nativeLibs =
         toLoad.getPackageMetaDataElement("NativeLibs").toString();
       if (nativeLibs.length() > 0) {
         String[] jarsWithLibs = nativeLibs.split(";");
         for (String entry : jarsWithLibs) {
           String[] jarAndEntries = entry.split(":");
