 		for ( Relationship r : rp.getRelationships().getRelationship() ) {

 			log.debug("For Relationship Id=" + r.getId() 
 					+ " Source is " + rp.getSourceP().getPartName() 
 					+ ", Target is " + r.getTarget() );

