 		boolean seenBackslash = false;

 		int c = getNext();
 		while (c != -1) {

 			if (seenBackslash) {
 				// Skip one character
 				seenBackslash = false;
 			}
 			else if (c == '\\') {
 				// Skip the next character
 				seenBackslash = true;
 			}
 			else {
