         else sb.append(',').append(' ');
         if (arg instanceof Node) {
           appendNode((Node)arg, sb);
         }
         else if (arg instanceof String) {
           sb.append('\"').append(StringUtil.escapeStringCharacters((String)arg)).append('\"');
         }
         else if (arg instanceof Number) {
           sb.append(arg);
         }
       }
